static const char* const kInfoComment[6][10] = {
 {"頭がすっきりしてるわ。","今日は筆の走りがいいわ。","ちゃんとはいてるわ。","バームクーヘンはどこ？","面倒だから、敵キャラは全部ゴリラでいいと思うの。","いつも通りね。","ふらふらするわ。","もう、今日はやる気にならないわ。","わたし、今、起きてる？","目の周りに星が飛んでて、きれい。"},
 {"イマジネーションが草津温泉のようにわき出てくるね！","３Ｄモデルがぬるぬる動いて、なめこみたいだね！","こーはいくん、たこ焼き食べに行こうよ！","こーはいくん、みそラーメン食べに行こうよ！","こーはいくん、ちゃんぽん食べに行こうよ！","面白いゲームにしようね！　よろしく哀愁！","体調なんて、どうにかなるもんだよ！","倒れても立ち上がる、不屈の精神が大切なんだよ！","なんだか楽しくなってきたね！","みんなで限界の向こう側へダッシュだね！"},
 {"今なら、いい調子で声出せそう。","今日は疲れも残ってないし、いつもよりがんばれるよ！","発声には、腹筋だけじゃなくて背筋も必要なんだよ。","腹筋鍛えても……お腹のお肉は減らないの。","やっぱり難しいな、さ行とた行……。","もっと発声の練習、しなきゃね。","えっと今日は後、あれやって、これやって……。","もうあかん、無理無理、倒れる……。","あれ……時間が飛んでる？","人間って、こんなに眠くなるんだね……。"},
 {"ちょっとだけ……本気出すか。","奇跡だ。今日は頭が冴えてる。書くなら今のうちだな。","えっと……誰に電話しなきゃいけないんだっけ。","ああ、大丈夫大丈夫。適当に何とかするよ。","俺の心配はいいから。","三点リーダーの扱いをどうしようか……。","ダメだな、頭が回らない。","誤植ばっかりじゃないか……！","気が狂いそうだ……。","何回同じことを繰り返せばいいんだ！"},
 {"質のいいトマトを仕入れた。","トマトのおかげで、体の調子は良好だ。","順調だ。","言うことは特に無いな。","そろそろＯＳ更新の時期か。","そろそろグラフィックボードの買い換え時期か。","体調には気をつけていたつもりだったが……。","睡眠時間が足りていないようだ……。","これは……想定以上だ……。","目算が甘かったな……。"},
 {"楽しいです！","色々なことがわかってきました！","がんばります！","がんばりたいです！","何かお仕事はありますか？","酢こんぶは足りてますか？","すみません……ほんとに、すみません……。","足は引っ張らないように……がんばります……。","頭がふらふらします！　がんばります！","酢こんぶがあれば大丈夫です！　がんばります！"},
};
